namespace ghidra.framework.data;




using ghidra.framework.model;
using ghidra.framework.model.TransactionInfo;
using ghidra.framework.store;
using ghidra.util;

class SynchronizedTransactionManager : AbstractTransactionManager {

	private LinkedList<SynchronizedTransaction> undoList = new();
	private LinkedList<SynchronizedTransaction> redoList = new();

	//private Map<DomainObjectAdapterDB, DomainObjectTransactionManager> domainObjects = new HashMap<DomainObjectAdapterDB, DomainObjectTransactionManager>();

	private DomainObjectAdapterDB[] domainObjects = new DomainObjectAdapterDB[0];
	private DomainObjectTransactionManager[] domainObjectTransactionManagers =
		new DomainObjectTransactionManager[0];

	private SynchronizedTransaction transaction;

	SynchronizedTransactionManager() : base()
    {
	}

	/* @Override */
	DomainObjectAdapterDB[] getDomainObjects() {
		return domainObjects;
	}

	/* @Override */
	void clearTransactions() {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			mgr.clearTransactions();
		}
		undoList.clear();
		redoList.clear();
	}

	void addDomainObject(DomainObjectAdapterDB domainObj)
    {
		lock (this) {
			AbstractTransactionManager mgr = domainObj.getTransactionManager();
			if (!(mgr is DomainObjectTransactionManager)) {
				throw new IllegalArgumentException("domain object has invalid transaction manager");
			}
			if (isLocked() || mgr.isLocked() || getCurrentTransactionInfo() != null ||
				mgr.getCurrentTransactionInfo() != null) {
				throw new LockException("domain object(s) are busy/locked");
			}
			if (!mgr.@lock("Transaction manager join")) {
				throw new LockException("domain object is busy");
			}
			clearTransactions();
			int count = domainObjects.length + 1;
			DomainObjectAdapterDB[] updatedDomainObjects = new DomainObjectAdapterDB[count];
			DomainObjectTransactionManager[] updatedManagers =
				new DomainObjectTransactionManager[count];
			Array.Copy(domainObjects, 0, updatedDomainObjects, 0, domainObjects.length);
			updatedDomainObjects[count - 1] = domainObj;
			Array.Copy(domainObjectTransactionManagers, 0, updatedManagers, 0,
				domainObjectTransactionManagers.length);
			updatedManagers[count - 1] =
				(DomainObjectTransactionManager) domainObj.getTransactionManager();
			domainObjects = updatedDomainObjects;
			domainObjectTransactionManagers = updatedManagers;
			domainObj.setTransactionManager(this);
			updatedManagers[count - 1].lockCount = 0;
		}
		notifyUndoableListeners();
	}

	void removeDomainObject(DomainObjectAdapterDB domainObj)
    {
		if (getCurrentTransactionInfo() != null) {
			throw new LockException("domain object has open transaction: " +
				getCurrentTransactionInfo().getDescription());
		}
		if (isLocked()) {
			throw new LockException("domain object is locked!");
		}
		if (domainObj.getTransactionManager() != this) {
			throw new IllegalArgumentException("domain object has different transaction manager");
		}
		int index = -1;
		for (int i = 0; i < domainObjects.length; i++) {
			if (domainObjects[i] == domainObj) {
				index = i;
				break;
			}
		}
		if (index < 0) {
			throw new IllegalArgumentException("invalid domain object");
		}
		clearTransactions();
		DomainObjectTransactionManager restoredMgr = domainObjectTransactionManagers[index];
		int count = domainObjects.length - 1;
		DomainObjectAdapterDB[] updatedDomainObjects = new DomainObjectAdapterDB[count];
		DomainObjectTransactionManager[] updatedManagers =
			new DomainObjectTransactionManager[count];
		Array.Copy(domainObjects, 0, updatedDomainObjects, 0, index);
		Array.Copy(domainObjectTransactionManagers, 0, updatedManagers, 0, index);
		if (index < count) {
			Array.Copy(domainObjects, index + 1, updatedDomainObjects, index, count - index);
			Array.Copy(domainObjectTransactionManagers, index + 1, updatedManagers, index,
				count - index);
		}
		domainObjects = updatedDomainObjects;
		domainObjectTransactionManagers = updatedManagers;

		domainObj.setTransactionManager(restoredMgr);
		restoredMgr.notifyUndoStackChanged();

		if (count == 1) {
			removeDomainObject(domainObjects[0]);
		}
		else {
			notifyUndoableListeners();
		}
	}

	/* @Override */
	void terminateTransaction(bool rollback, bool notify) {
		if (transaction == null || transactionTerminated) {
			return;
		}
		foreach (AbstractTransactionManager mgr in domainObjectTransactionManagers) {
			mgr.terminateTransaction(rollback, false);
		}
		transactionTerminated = true;
		if (notify) {
			notifyEndTransaction();
		}
	}

	/* @Override */
	int startTransaction(DomainObjectAdapterDB @object, string description,
			AbortedTransactionListener listener, bool force, bool notify) {

		if (transaction == null) {

			if (!force) {
				verifyNoLock();
			}

			transactionTerminated = false;
			transaction = new SynchronizedTransaction(domainObjectTransactionManagers);
			int txId = transaction.addEntry(@object, description, listener);
			if (notify) {
				notifyStartTransaction();
			}
			return txId;
		}
		if (transactionTerminated) {
			Msg.warn(this,
				"Aborted transaction still pending, new transaction will also be aborted: " +
					description);
		}
		int txId = transaction.addEntry(@object, description, listener);
		if (notify) {
			notifyStartTransaction();
		}
		return txId;
	}

	/* @Override */
	TransactionInfo endTransaction(DomainObjectAdapterDB @object, int transactionID,
			bool commit, bool notify) {
		if (transaction == null) {
			throw new IllegalStateException("No transaction is open");
		}
		TransactionInfo returnedTransaction = transaction;
		transaction.endEntry(@object, transactionID, commit && !transactionTerminated);
		Status status = transaction.getStatus();
		if (status == Status.COMMITTED) {
			bool committed = transaction.endAll(true);
			if (committed) {
				redoList.clear();
				undoList.addLast(transaction);
				if (undoList.size() > NUM_UNDOS) {
					undoList.removeFirst();
				}
			}
			transaction = null;
			if (notify) {
				notifyEndTransaction();
			}
		}
		else if (status == Status.ABORTED) {
			if (!transactionTerminated) {
				transaction.endAll(false);
			}
			transaction = null;
			if (notify) {
				notifyEndTransaction();
			}
		}
		return returnedTransaction;
	}

	/**
	 * Returns the undo stack depth.
	 * (The number of items on the undo stack)
	 * This method is for JUnits.
	 * @return the undo stack depth
	 */
	/* @Override */
	int getUndoStackDepth() {
		return undoList.size();
	}

	/* @Override */
	bool canRedo() {
		if (redoList.size() > 0) {
			foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
				if (mgr.canRedo()) {
					return true;
				}
			}
		}
		return false;
	}

	/* @Override */
	bool canUndo() {
		if (undoList.size() > 0) {
			foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
				if (mgr.canUndo()) {
					return true;
				}
			}
		}
		return false;
	}

	/* @Override */
	string getRedoName() {
		if (redoList.size() > 0) {
			TransactionInfo t = redoList.getLast();
			return t.getDescription();
		}
		return "";
	}

	/* @Override */
	string getUndoName() {
		if (undoList.size() > 0) {
			TransactionInfo t = undoList.getLast();
			return t.getDescription();
		}
		return "";
	}

	/* @Override */
	List<string> getAllUndoNames() {
		List<string> descriptions = new();
		foreach (SynchronizedTransaction tx in undoList) {
			descriptions.add(tx.getDescription());
		}
		Collections.reverse(descriptions);
		return descriptions;
	}

	/* @Override */
	List<string> getAllRedoNames() {
		List<string> descriptions = new();
		foreach (SynchronizedTransaction tx in redoList) {
			descriptions.add(tx.getDescription());
		}
		Collections.reverse(descriptions);
		return descriptions;
	}

	/* @Override */
	TransactionInfo getCurrentTransactionInfo() {
		return transaction;
	}

	/* @Override */
	void doRedo(bool notify)
    {
		if (canRedo()) {
			SynchronizedTransaction t = redoList.removeLast();
			undoList.addLast(t);
			t.redo();
			if (notify) {
				notifyUndoableListeners();
			}
		}
	}

	/* @Override */
	void doUndo(bool notify)
    {
		if (canUndo()) {
			SynchronizedTransaction t = undoList.removeLast();
			redoList.addLast(t);
			t.undo();
			if (notify) {
				notifyUndoableListeners();
			}
		}
	}

	/* @Override */
	void clearUndo(bool notifyListeners) {
		if (!undoList.isEmpty() || !redoList.isEmpty()) {

			undoList.clear();
			redoList.clear();

			foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
				mgr.clearUndo(false);
			}
			if (notifyListeners) {
				notifyUndoableListeners();
			}
		}
	}

	/* @Override */
	void doClose(DomainObjectAdapterDB @object) {
		try {
			removeDomainObject(@object);
		}
		catch (LockException e) {
			throw new IllegalStateException(e);
		}
		@object.getTransactionManager().close(@object);
	}

	/* @Override */
	void addTransactionListener(DomainObjectAdapterDB @object,
			TransactionListener listener) {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			if (mgr.getDomainObject() == @object) {
				mgr.addTransactionListener(@object, listener);
				return;
			}
		}
		throw new IllegalArgumentException("invalid domain object");
	}

	/* @Override */
	void removeTransactionListener(DomainObjectAdapterDB @object,
			TransactionListener listener) {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			if (mgr.getDomainObject() == @object) {
				mgr.removeTransactionListener(@object, listener);
				return;
			}
		}
		throw new IllegalArgumentException("invalid domain object");
	}

	private void notifyUndoableListeners() {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			mgr.notifyUndoStackChanged();
		}
	}

	private void notifyStartTransaction() {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			mgr.notifyStartTransaction(transaction);
		}
	}

	private void notifyEndTransaction() {
		foreach (DomainObjectTransactionManager mgr in domainObjectTransactionManagers) {
			mgr.notifyEndTransaction();
		}
	}

